// static
bool StructTraits<::recipes::mojom::Recipe::DataView, ::recipes::mojom::RecipePtr>::Read(
    ::recipes::mojom::Recipe::DataView input,
    ::recipes::mojom::RecipePtr* output) {
  bool success = true;
  ::recipes::mojom::RecipePtr result(::recipes::mojom::Recipe::New());
  
      if (success && !input.ReadName(&result->name))
        success = false;
      if (success && !input.ReadImageUrl(&result->image_url))
        success = false;
      if (success && !input.ReadInfo(&result->info))
        success = false;
      if (success && !input.ReadSiteName(&result->site_name))
        success = false;
      if (success && !input.ReadTargetUrl(&result->target_url))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::recipes::mojom::RelatedSearch::DataView, ::recipes::mojom::RelatedSearchPtr>::Read(
    ::recipes::mojom::RelatedSearch::DataView input,
    ::recipes::mojom::RelatedSearchPtr* output) {
  bool success = true;
  ::recipes::mojom::RelatedSearchPtr result(::recipes::mojom::RelatedSearch::New());
  
      if (success && !input.ReadText(&result->text))
        success = false;
      if (success && !input.ReadTargetUrl(&result->target_url))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::recipes::mojom::Task::DataView, ::recipes::mojom::TaskPtr>::Read(
    ::recipes::mojom::Task::DataView input,
    ::recipes::mojom::TaskPtr* output) {
  bool success = true;
  ::recipes::mojom::TaskPtr result(::recipes::mojom::Task::New());
  
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadName(&result->name))
        success = false;
      if (success && !input.ReadRecipes(&result->recipes))
        success = false;
      if (success && !input.ReadRelatedSearches(&result->related_searches))
        success = false;
  *output = std::move(result);
  return success;
}

