RecipesHandlerAsyncWaiter::RecipesHandlerAsyncWaiter(
    RecipesHandler* proxy) : proxy_(proxy) {}

RecipesHandlerAsyncWaiter::~RecipesHandlerAsyncWaiter() = default;

void RecipesHandlerAsyncWaiter::GetPrimaryTask(
    TaskPtr* out_task) {
  base::RunLoop loop;
  proxy_->GetPrimaryTask(
      base::BindOnce(
          [](base::RunLoop* loop,
             TaskPtr* out_task
,
             TaskPtr task) {*out_task = std::move(task);
            loop->Quit();
          },
          &loop,
          out_task));
  loop.Run();
}

TaskPtr RecipesHandlerAsyncWaiter::GetPrimaryTask(
    ) {
  TaskPtr async_wait_result;
  GetPrimaryTask(&async_wait_result);
  return async_wait_result;
}






